// Show constellation artwork
ConstellationMgr.setFlagArt(true);

// Hide constellation artwork
ConstellationMgr.setFlagArt(false);

// Toggle artwork visibility
var currentState = ConstellationMgr.getFlagArt();
ConstellationMgr.setFlagArt(!currentState);

if(ConstellationMgr.getFlagArt()) {
    core.debug("Constellation artwork is visible");
} else {
    core.debug("Constellation artwork is hidden");
}

// Fast fade (0.5 seconds)
ConstellationMgr.setArtFadeDuration(0.5);
ConstellationMgr.setFlagArt(true);

// Slow dramatic fade (3 seconds)
ConstellationMgr.setArtFadeDuration(3.0);
ConstellationMgr.setFlagArt(false);

// Get current fade duration
var fadeTime = ConstellationMgr.getArtFadeDuration();
core.debug("Art fade duration: " + fadeTime + " seconds");

// Set artwork to full brightness
ConstellationMgr.setArtIntensity(1.0);

// Set artwork to half transparency
ConstellationMgr.setArtIntensity(0.5);

// Get current intensity
var intensity = ConstellationMgr.getArtIntensity();
core.debug("Art intensity: " + intensity);

// Configure FOV-based fading
ConstellationMgr.setArtIntensityMinimumFov(1.0);
ConstellationMgr.setArtIntensityMaximumFov(2.0);

// Artwork fades completely below 0.5 degrees
ConstellationMgr.setArtIntensityMinimumFov(0.5);

// Artwork reaches full brightness at 2 degrees
ConstellationMgr.setArtIntensityMaximumFov(2.0);

var minFov = ConstellationMgr.getArtIntensityMinimumFov();
core.debug("Art minimum FOV: " + minFov);

ConstellationMgr.setArtIntensityMaximumFov(3.0);
var maxFov = ConstellationMgr.getArtIntensityMaximumFov();
core.debug("Art max FOV: " + maxFov);

// Set boundaries to red
var red = core.vec3f(1.0, 0.0, 0.0);
ConstellationMgr.setBoundariesColor(red);

// Set boundaries to light blue
var lightBlue = core.vec3f(0.5, 0.8, 1.0);
ConstellationMgr.setBoundariesColor(lightBlue);

// Get current boundaries color
var color = ConstellationMgr.getBoundariesColor();
core.debug("Boundaries color: R=" + color[0] + ", G=" + color[1] + ", B=" + color[2]);

// Show constellation boundaries
ConstellationMgr.setFlagBoundaries(true);

// Hide constellation boundaries
ConstellationMgr.setFlagBoundaries(false);

// Combined with other constellation elements
ConstellationMgr.setFlagLines(true);
ConstellationMgr.setFlagBoundaries(true);

if(ConstellationMgr.getFlagBoundaries()) {
    core.debug("Constellation boundaries are visible");
}

ConstellationMgr.setBoundariesFadeDuration(1.5);
ConstellationMgr.setFlagBoundaries(true);

var fadeDuration = ConstellationMgr.getBoundariesFadeDuration();
core.debug("Boundaries fade duration: " + fadeDuration);

// Enable isolation mode
ConstellationMgr.setFlagIsolateSelected(true);
ConstellationMgr.selectConstellation("Orion");
// Only Orion is now visible

// Disable isolation mode
ConstellationMgr.setFlagIsolateSelected(false);
// All constellations become visible

var isIsolated = ConstellationMgr.getFlagIsolateSelected();
core.debug("Isolation mode active: " + isIsolated);

if(ConstellationMgr.getFlagIsolateSelected()) {
    core.debug("Isolation mode is active");
}

// Enable single constellation pick mode
ConstellationMgr.setFlagConstellationPick(true);
ConstellationMgr.setFlagIsolateSelected(true);

// Select Orion - only Orion visible
ConstellationMgr.selectConstellation("Orion");

// Select Taurus - replaces Orion, only Taurus visible
ConstellationMgr.selectConstellation("Taurus");

var pickMode = ConstellationMgr.getFlagConstellationPick();
core.debug("Single pick mode: " + pickMode);

if(ConstellationMgr.getFlagConstellationPick()) {
    core.debug("Single constellation pick mode is on");
}

// Set constellation lines to cyan
var cyan = core.vec3f(0.0, 0.8, 0.9);
ConstellationMgr.setLinesColor(cyan);

// Set to golden
var gold = core.vec3f(1.0, 0.84, 0.0);
ConstellationMgr.setLinesColor(gold);

// Get current lines color
var color = ConstellationMgr.getLinesColor();
core.debug("Lines color: RGB(" + color[0] + ", " + color[1] + ", " + color[2] + ")");

// Show constellation lines
ConstellationMgr.setFlagLines(true);

// Hide constellation lines
ConstellationMgr.setFlagLines(false);

// Show all constellation elements
ConstellationMgr.setFlagLines(true);
ConstellationMgr.setFlagLabels(true);
ConstellationMgr.setFlagBoundaries(true);

if(ConstellationMgr.getFlagLines()) {
    core.debug("Constellation lines are visible");
}

ConstellationMgr.setLinesFadeDuration(1.0);
var fade = ConstellationMgr.getLinesFadeDuration();
core.debug("Lines fade duration: " + fade);

// Set labels to white
var white = core.vec3f(1.0, 1.0, 1.0);
ConstellationMgr.setLabelsColor(white);

// Set labels to light yellow
var lightYellow = core.vec3f(1.0, 1.0, 0.6);
ConstellationMgr.setLabelsColor(lightYellow);

var color = ConstellationMgr.getLabelsColor();
core.debug("Labels color: RGB(" + color[0] + ", " + color[1] + ", " + color[2] + ")");

// Show constellation labels
ConstellationMgr.setFlagLabels(true);

// Hide constellation labels
ConstellationMgr.setFlagLabels(false);

if(ConstellationMgr.getFlagLabels()) {
    core.debug("Constellation labels are visible");
}

// Set hulls to red
var red = core.vec3f(1.0, 0.0, 0.0);
ConstellationMgr.setHullsColor(red);

var color = ConstellationMgr.getHullsColor();

// Show constellation hulls
ConstellationMgr.setFlagHulls(true);

// Hide constellation hulls
ConstellationMgr.setFlagHulls(false);

if(ConstellationMgr.getFlagHulls()) {
    core.debug("Constellation hulls are visible");
}

// Larger font for better readability
ConstellationMgr.setFontSize(18);

// Default size
ConstellationMgr.setFontSize(15);

var fontSize = ConstellationMgr.getFontSize();
core.debug("Font size: " + fontSize + " pixels");

// Thin elegant lines
ConstellationMgr.setConstellationLineThickness(1);

// Thick visible lines
ConstellationMgr.setConstellationLineThickness(2);

var thickness = ConstellationMgr.getConstellationLineThickness();
core.debug("Line thickness: " + thickness);

// Set zodiac to gold
var gold = core.vec3f(1.0, 0.84, 0.0);
ConstellationMgr.setZodiacColor(gold);

var color = ConstellationMgr.getZodiacColor();

// Show zodiac lines
ConstellationMgr.setFlagZodiac(true);

// Hide zodiac lines
ConstellationMgr.setFlagZodiac(false);

if(ConstellationMgr.getFlagZodiac()) {
    core.debug("Zodiac is visible");
}

if(ConstellationMgr.getFlagZodiac()) {
    core.debug("Zodiac lines are visible");
}

// Set lunar system to cyan
var cyan = core.vec3f(0.0, 1.0, 0.5);
ConstellationMgr.setLunarSystemColor(cyan);

var color = ConstellationMgr.getLunarSystemColor();

// Show lunar mansions
ConstellationMgr.setFlagLunarSystem(true);

// Hide lunar mansions
ConstellationMgr.setFlagLunarSystem(false);

if(ConstellationMgr.getFlagLunarSystem()) {
    core.debug("Lunar system is visible");
}

if(ConstellationMgr.getFlagLunarSystem()) {
    core.debug("Lunar system is visible");
}

// Deselect all constellations
ConstellationMgr.deselectConstellations();

// Clear selection after a presentation
ConstellationMgr.selectConstellation("Orion");
core.wait(3);
ConstellationMgr.deselectConstellations();

// Select all constellations
ConstellationMgr.selectAllConstellations();

// Enable isolation then show all
ConstellationMgr.setFlagIsolateSelected(true);
ConstellationMgr.selectAllConstellations();

// Select Orion constellation
ConstellationMgr.selectConstellation("Orion");
core.moveToObject("Betelgeuse", 2);

// Select Ursa Major (Big Dipper)
ConstellationMgr.selectConstellation("Ursa Major");

// Select Leo
ConstellationMgr.selectConstellation("Leo");

// Select constellation where Venus is currently located
ConstellationMgr.selectConstellationByObjectName("Venus");

// Select constellation containing Sirius
ConstellationMgr.selectConstellationByObjectName("Sirius");

// Select Mars' current constellation
ConstellationMgr.selectConstellationByObjectName("Mars");

var info = core.getObjectInfo("Mars");
core.debug("Mars is in: " + info["constellation-id"]);

// Select then deselect Orion
ConstellationMgr.selectConstellation("Orion");
core.wait(3);
ConstellationMgr.deselectConstellation("Orion");

// Select multiple and then remove one
ConstellationMgr.selectConstellation("Orion");
ConstellationMgr.selectConstellation("Taurus");
ConstellationMgr.deselectConstellation("Orion");
// Only Taurus remains selected

var constellations = ConstellationMgr.getConstellationsEnglishNames();
core.debug("Total constellations: " + constellations.length);

// Print first 10 constellations
for(var i=0; i<Math.min(10, constellations.length); i++) {
    core.debug((i+1) + ". " + constellations[i]);
}

if(ConstellationMgr.hasZodiac()) {
    core.debug("Current sky culture has zodiac definition");
    var zodiacName = ConstellationMgr.getZodiacSystemName();
    core.debug("Zodiac name: " + zodiacName);
} else {
    core.debug("No zodiac defined in this sky culture");
}

if(ConstellationMgr.hasLunarSystem()) {
    core.debug("Current sky culture has lunar mansions");
    var lunarName = ConstellationMgr.getLunarSystemName();
    core.debug("Lunar system name: " + lunarName);
}

var zodiacName = ConstellationMgr.getZodiacSystemName();
if(zodiacName) {
    core.debug("Zodiac system: " + zodiacName);
}

var lunarName = ConstellationMgr.getLunarSystemName();
if(lunarName) {
    core.debug("Lunar system: " + lunarName);
}

// Get zodiac coordinate for Mars
var marsPos = core.getObjectInfo("Mars")["position"];
// Note: Getting Vec3d position requires additional steps
// This example shows the concept

// Get zodiac coordinate for the Sun on today's date
core.setDate("now");
var sunInfo = core.getObjectInfo("Sun");
core.debug("Sun's zodiac position: " + sunInfo["zodiac"]);

// Get lunar mansion for the Moon's position
var moonInfo = core.getObjectInfo("Moon");
core.debug("Moon's lunar mansion: " + moonInfo["lunar-system"]);

// Get full name for Orion
var fullName = ConstellationMgr.getIAUconstellationName("Ori");
core.debug("Ori = " + fullName);

// Get full name for Ursa Major
var umaName = ConstellationMgr.getIAUconstellationName("UMa");
core.debug("UMa = " + umaName);

// Get full name for Leo
var leoName = ConstellationMgr.getIAUconstellationName("Leo");
core.debug("Leo = " + leoName);

// Reload sky culture after manual file edits
core.debug("Reloading sky culture...");
ConstellationMgr.reloadSkyCulture();
core.debug("Sky culture reloaded");

// Export hull areas to CSV file
ConstellationMgr.outputHullAreas("my_hull_analysis");
core.debug("Hull areas exported to user data directory");

// Export all bright stars in Orion
ConstellationMgr.starsInHullOf("Orion", true, 6.0, "orion_stars");
core.debug("Orion stars exported to CSV");

// Export all stars (including faint ones) in Ursa Major
ConstellationMgr.starsInHullOf("Ursa Major", false, 25.0, "ursa_major_stars");
